/* Image zoom  */
.view-content  img:not([class="emoji"]) {
  cursor: zoom-in;
}

.workspace-leaf-content[data-type="markdown"] .view-content  img:not([class="emoji"]) {
  cursor: zoom-in;
  display: block;
}

.view-content img:not([class="emoji"]):active {
  cursor: zoom-out;    
  position: fixed;
  object-fit: contain;
  height: 100%;
  width: 100%;
  padding: 0;
  top: 50%;  
  left: 0;
  right: 0;
  bottom: 0;
  transform: translateY(-50%);
  z-index: 200;
  background-image: url("data:image/svg+xml;base64,");
}

