/* =========================================*/
/* =========tapes pins and stickies=========*/
/* =========================================*/
/* thanks to death_au, Gabroel and Lithou from Obsidian Members Group on Discord */
.stickies {
  text-align: center;
  transition: width 2s;
  padding: 5px;
  margin: 18px;
  position: relative;
  float: right;
  right: -10px;
  width: 30%;
  background-color: var(--stickies-color-1);
  -webkit-transform: rotate(0deg);
  -moz-transform: rotate(0deg);
  -o-transform: rotate(0deg);
  -ms-transform: rotate(0deg);
  transform: rotate(2deg);
  transition: all 2s ease;
  z-index: 1;
  padding-top: 10px;
  padding-bottom: 10px;
  border-radius: 0px;
  color: black;
}

.stickies::after {
  content: "";
  left: -5%;
  top: -10px;
  height: 40px;
  width: 15px;
  border-radius: 10px;
  border: 3px solid #979797;
  display: inline-block;
  position: absolute;
  -webkit-transform: rotate(0deg);
  -moz-transform: rotate(0deg);
  -o-transform: rotate(0deg);
  -ms-transform: rotate(0deg);
  transform: rotate(-11deg);
  z-index: 11;
}

.stickies::before {
  width: 11px;
  height: 20px;
  content: "";
  display: inline-block;
  position: absolute;
  left: -3.5%;
  top: -2px;
  border-radius: 10px;
  border: 3px solid #979797;
  border-bottom: 0;
  border-bottom-right-radius: 0;
  border-bottom-left-radius: 0;
  z-index: 10;
  -webkit-transform: rotate(0deg);
  -moz-transform: rotate(0deg);
  -o-transform: rotate(0deg);
  -ms-transform: rotate(0deg);
  transform: rotate(-11deg);
}

.stickies2 {
  position: relative;
  float: left;
  box-shadow: 0 10px 10px 2px #9191912d;
  width: 30%;
  background-color: var(--stickies-color-2);
  -webkit-transform: rotate(0deg);
  -moz-transform: rotate(0deg);
  -o-transform: rotate(0deg);
  -ms-transform: rotate(0deg);
  transform: rotate(-2deg);
  transition: all 2s ease;
  z-index: 1;
  padding: 20px;
  margin: 10px;
  color: black;
}

.stickies2::after {
  content: "";
  display: block;
  height: 32px;
  width: 2px;
  position: absolute;
  left: 50%;
  top: -10px;
  z-index: 1;
  border-radius: 50%;
  display: inline-block;
  height: 15px;
  width: 15px;
  border: 1px;
  box-shadow: inset -10px -10px 10px #f0b7a4, inset 3px 3px 5px;
}

.to-recall {
  position: relative;
  float: left;
  width: 30%;
  background-color: var(--text-normal);
  border-radius: 2%;
  -webkit-transform: rotate(0deg);
  -moz-transform: rotate(0deg);
  -o-transform: rotate(0deg);
  -ms-transform: rotate(0deg);
  transform: rotate(0deg);
  z-index: 1;
  padding: 8px;
  margin-right: 8px;
  margin-top: 20px;
  font-weight: bold;
  font-family: Cooper;
  color: var(--text-normal);
}

.to-recall:hover {
  cursor: pointer;
} 

.to-recall:active {
  position: relative;
  max-width: 30%;
  background-color: transparent;
  border-radius: 5%;
  transition: all 300ms ease;
  color: var(--text-normal);
}

.to-recall::after {
  content: "Click";
  position: absolute;
  font-size: 12px;
  top: 1px;
  right: 5px;
  font-weight: 600;
  font-family: Arial;
  color: var(--background-primary);
}

.to-recall:active:after {
  display: none;
}

.to-recall::before {
  content: " To Recall";
  display: inline-block;
  position: absolute;
  top: -20px;
  left: -8px;
  border-radius: 10px;
  font-size: 14px;
  font-weight: bold;
  font-family: OCR A;
  color: #858585;
  white-space: pre;
}

